examples.template:
@OptIn(ExperimentalMonarchApi::class)
MonarchDocumentRelations(
    relations = relations,
    candidates = library,
    onOpen = { /* The app navigates to the document. */ },
    onAdd = { id, type ->
        // The app stores the relation on its server here.
        library.firstOrNull { it.id == id }?.let { target ->
            relations = relations + MonarchDocumentRelation("r" + (relations.size + 1), type, target)
        }
    },
    onRemove = { id -> relations = relations.filterNot { it.id == id } },
)

